def encode(message):
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }
    result = []
    for char in message:
        if char.islower():
            if char in vowels:
                result.append(vowel_map[char])
            else:
                result.append(char.swapcase())
        elif char.isupper():
            if char in vowels:
                result.append(vowel_map[char])
            else:
                result.append(char.swapcase())
        else:
            result.append(char)
    return ''.join(result)
